import "server-only";
import { and, eq, inArray, sql } from "drizzle-orm";
import { getDb, schema } from "@/db";
import type { Contact, QuizSubmission } from "@/db/schema";
import { OFFERS, STRATEGY_CALL_HREF, STRATEGY_CALL_SLUG, type Recommendation } from "@/lib/assessment";
import { ipRateLimitKey, rateLimit } from "@/lib/rate-limit";
import { getActiveMeetingType } from "@/lib/scheduling";
import { formatMoney } from "@/lib/utils";

/** Result tokens are 32 hex chars (generated by the DB default or the submit action). */
export const RESULT_TOKEN_RE = /^[a-zA-Z0-9]{16,64}$/;

export type SubmissionWithContact = {
  submission: QuizSubmission;
  /**
   * Only the address the submission was made with. The contact's stored name and company may belong to
   * someone else (anyone can type any email), so results show what was entered: `submittedContact()`.
   */
  contact: Pick<Contact, "id" | "email">;
};

export async function getSubmissionByToken(token: string): Promise<SubmissionWithContact | null> {
  if (!RESULT_TOKEN_RE.test(token)) return null;
  const db = await getDb();
  const [row] = await db
    .select({
      submission: schema.quizSubmissions,
      contact: {
        id: schema.contacts.id,
        email: schema.contacts.email,
      },
    })
    .from(schema.quizSubmissions)
    .innerJoin(schema.contacts, eq(schema.contacts.id, schema.quizSubmissions.contactId))
    .where(eq(schema.quizSubmissions.resultToken, token))
    .limit(1);
  return row ?? null;
}

export type OfferDetails = {
  recommendation: Recommendation;
  kind: "course" | "consulting";
  title: string;
  subtitle: string;
  /** Relative URL of the offer page. */
  href: string;
  cta: string;
  priceCents: number | null;
  compareAtCents: number | null;
  coverEmoji: string | null;
  audience: string | null;
  level: string | null;
  durationMin: number | null;
  /** e.g. "$297" or "Free 45-minute call" — used in AI prompts and emails. */
  priceLabel: string | null;
};

/** Loads the live title / price for the recommended offer, falling back to static copy. */
export async function loadOffer(rec: Recommendation): Promise<OfferDetails> {
  const offer = OFFERS[rec];
  const base: OfferDetails = {
    recommendation: rec,
    kind: offer.kind,
    title: offer.name,
    subtitle: offer.blurb,
    href: offer.href,
    cta: offer.cta,
    priceCents: null,
    compareAtCents: null,
    coverEmoji: null,
    audience: null,
    level: null,
    durationMin: null,
    priceLabel: null,
  };
  try {
    if (offer.kind === "course") {
      const db = await getDb();
      const [course] = await db
        .select()
        .from(schema.courses)
        .where(and(eq(schema.courses.slug, offer.slug), eq(schema.courses.published, true)))
        .limit(1);
      // Course unpublished or renamed: send people to the catalog rather than a 404.
      if (!course) return { ...base, href: "/courses", cta: "Browse our courses" };
      return {
        ...base,
        title: course.title,
        subtitle: course.subtitle || offer.blurb,
        href: `/courses/${course.slug}`,
        priceCents: course.priceCents,
        compareAtCents: course.compareAtCents,
        coverEmoji: course.coverEmoji,
        audience: course.audience,
        level: course.level,
        priceLabel: course.priceCents > 0 ? formatMoney(course.priceCents) : "Free",
      };
    }
    const meeting = await getActiveMeetingType(offer.slug);
    if (!meeting) return { ...base, href: "/consulting", cta: "Learn about AI implementation" };
    return {
      ...base,
      subtitle: meeting.description || offer.blurb,
      durationMin: meeting.durationMin,
      priceCents: meeting.priceCents,
      priceLabel: meeting.priceCents > 0 ? formatMoney(meeting.priceCents) : `Free ${meeting.durationMin}-minute discovery call`,
    };
  } catch (err) {
    console.error("[assessment] failed to load offer", rec, err);
    return base;
  }
}

export type StrategyCall = { href: string; durationMin: number | null; free: boolean };

export async function loadStrategyCall(): Promise<StrategyCall> {
  try {
    const meeting = await getActiveMeetingType(STRATEGY_CALL_SLUG);
    if (meeting) return { href: STRATEGY_CALL_HREF, durationMin: meeting.durationMin, free: meeting.priceCents === 0 };
  } catch (err) {
    console.error("[assessment] failed to load strategy call", err);
  }
  return { href: "/book", durationMin: null, free: true };
}

/** Appends ?name=&email= so booking forms open pre-filled (booking pages only). */
export function withPrefill(href: string, person: { name?: string | null; email?: string | null }): string {
  if (!href.startsWith("/book/")) return href;
  const params = new URLSearchParams();
  if (person.name) params.set("name", person.name);
  if (person.email) params.set("email", person.email);
  const qs = params.toString();
  return qs ? `${href}?${qs}` : href;
}

const DAY_SEC = 24 * 60 * 60;

/**
 * Limits on Claude-written plans: each one is a medium-effort generation billed to the owner, and a
 * results token is all it takes to ask for one.
 */
export const PLAN_LIMITS = {
  /** One generation per submission at a time (outlasts the plan route's 60s maxDuration). */
  leaseSec: 90,
  /** Per submission per day: a visitor who leaves mid-stream gets no stored plan, so allow a couple of retries. */
  perSubmissionPerDay: 3,
  /** Generations started per IP address (IPv6: /64 network) per day. */
  perIpPerDay: 30,
  /** Site-wide per day: a ceiling on spend however many addresses are used. */
  globalPerDay: 500,
} as const;

export type PlanRefusal = "in_progress" | "ip_limit" | "submission_limit" | "daily_limit";
export type PlanClaim = { ok: true } | { ok: false; reason: PlanRefusal };

/** The `rate_limits` keys behind PLAN_LIMITS (the per-IP one matches `rateLimitByIp("assessment-plan:day")`). */
export function planBudgetKeys(submissionId: string, ip: string) {
  return {
    lease: `assessment-plan:lease:${submissionId}`,
    submission: `assessment-plan:sub:${submissionId}`,
    ip: `assessment-plan:day:${ipRateLimitKey(ip)}`,
    global: "assessment-plan:global",
  };
}

/** Gives back hits a refused claim recorded, so a refusal never spends a budget. Best effort. */
async function refundHits(keys: string[]): Promise<void> {
  try {
    const db = await getDb();
    await db
      .update(schema.rateLimits)
      .set({ count: sql`greatest(${schema.rateLimits.count} - 1, 0)` })
      .where(inArray(schema.rateLimits.key, keys));
  } catch (err) {
    console.error("[assessment] failed to refund the plan budget", err);
  }
}

/**
 * Claims one Claude plan generation for a submission (call only when AI is configured). When it isn't
 * granted, the caller streams the deterministic plan instead, unsaved, so a later visit can still get
 * a Claude-written one. `ip` is the client IP (`clientIp()`; a parameter so tests can run outside a request).
 *
 * The daily budgets are all-or-nothing: each counter is incremented atomically, and when one refuses,
 * this call's hits on every daily counter are given back, so refused visits (say on a day the site-wide
 * ceiling is reached) don't use up a submission's or an address's allowance. The narrowest budget is
 * checked first, so the shared site-wide counter is only touched once the others have passed. The
 * lease is kept either way: it limits a submission to one attempt per `leaseSec`.
 */
export async function claimPlanGeneration(submissionId: string, ip: string): Promise<PlanClaim> {
  const keys = planBudgetKeys(submissionId, ip);
  // Single flight: concurrent requests for one token (or a quick retry) don't each start a generation.
  const lease = await rateLimit(keys.lease, 1, PLAN_LIMITS.leaseSec);
  if (!lease.ok) return { ok: false, reason: "in_progress" };

  const budgets: { key: string; limit: number; reason: PlanRefusal }[] = [
    { key: keys.submission, limit: PLAN_LIMITS.perSubmissionPerDay, reason: "submission_limit" },
    { key: keys.ip, limit: PLAN_LIMITS.perIpPerDay, reason: "ip_limit" },
    { key: keys.global, limit: PLAN_LIMITS.globalPerDay, reason: "daily_limit" },
  ];
  const hit: string[] = [];
  for (const budget of budgets) {
    const { ok } = await rateLimit(budget.key, budget.limit, DAY_SEC);
    hit.push(budget.key);
    if (!ok) {
      await refundHits(hit);
      return { ok: false, reason: budget.reason };
    }
  }
  return { ok: true };
}
